// Simulate the threshold checking logic
function generateReport({ evaluations, thresholds }) {
  const report = {
    metrics: evaluations
  };

  if (thresholds && typeof thresholds === 'object') {
    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, minScore] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score >= minScore;

      if (!passed) {
        allPassed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min: minScore,
        score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

// Test cases
console.log('Test 1: All thresholds pass');
let report = generateReport({
  evaluations: [
    { id: 'exact_match', score: 0.95 },
    { id: 'toxicity', score: 0.98 }
  ],
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.95
  }
});
console.log('Passed:', report.passed);
console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));
console.log('');

console.log('Test 2: One threshold fails');
report = generateReport({
  evaluations: [
    { id: 'exact_match', score: 0.85 },
    { id: 'toxicity', score: 0.98 }
  ],
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.95
  }
});
console.log('Passed:', report.passed);
console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));
console.log('');

console.log('Test 3: Metric with null score fails threshold');
report = generateReport({
  evaluations: [
    { id: 'exact_match', score: null },
    { id: 'toxicity', score: 0.98 }
  ],
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.95
  }
});
console.log('Passed:', report.passed);
console.log('Thresholds:', JSON.stringify(report.thresholds, null, 2));
console.log('');

console.log('Test 4: No thresholds');
report = generateReport({
  evaluations: [
    { id: 'exact_match', score: 0.85 },
    { id: 'toxicity', score: 0.98 }
  ]
});
console.log('Report has passed field:', report.hasOwnProperty('passed'));
console.log('Report has thresholds field:', report.hasOwnProperty('thresholds'));
EOF
